package org.apache.commons.math.analysis.solvers;

import org.apache.commons.math.analysis.UnivariateFunction;
import org.apache.commons.math.exception.NoBracketingException;
import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Math_40_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        BracketingNthOrderBrentSolver solver = new BracketingNthOrderBrentSolver(1e-10, 1e-14, 1e-15, 5);
        try {
            // This function has a very flat slope near the root at x = 0.5
            UnivariateFunction function = new UnivariateFunction() {
                public double value(double x) {
                    return Math.pow(x - 0.5, 5);
                }
            };
            double result = solver.solve(100, function, 0, 1);
            // The expected result should be close to 0.5
            assertEquals(0.5, result, 1e-10);
        } catch (NoBracketingException e) {
            fail("NoBracketingException was thrown unexpectedly.");
        }
    }
}

